//go:build generate

package main

import (
	"bytes"
	"crypto/rand"
	"encoding/hex"
	"os"
	"os/exec"
	"path/filepath"
	"text/template"

	"github.com/caarlos0/log"
)

//go:generate go run gen.go

const (
	// keysLength é em BYTES; o hex terá o dobro (2 * keysLength) caracteres
	keysLength = 44
	keysNumber = 512
	fileName   = "generated_keys.go"
	tmpl       = `// Code generated by 'go generate ./...'; DO NOT EDIT.
// Package cryptography holds autogenerated keys.

package cryptography

const (
	KeysLength = {{.KeysLength}} // bytes; hex string tem 2x
)

var StringKeys = []string{
{{- range .Keys }}
	"{{ . }}",
{{- end }}
}
`
)

// generateKey cria uma chave de tamanho `size` em bytes, codificada em hex.
func generateKey(size int) string {
	key := make([]byte, size)
	if _, err := rand.Read(key); err != nil {
		log.WithError(err).Fatal("error generating random key")
	}
	return hex.EncodeToString(key)
}

type keysData struct {
	Keys       []string
	KeysLength int
}

func main() {
	// prepara template
	newTmpl, err := template.New("keys").Parse(tmpl)
	if err != nil {
		log.WithError(err).Fatal("error parsing template")
	}

	data := keysData{
		Keys:       make([]string, 0, keysNumber),
		KeysLength: keysLength,
	}

	for i := 0; i < keysNumber; i++ {
		data.Keys = append(data.Keys, generateKey(keysLength))
	}

	// gera o conteúdo em buffer
	var buf bytes.Buffer
	if err := newTmpl.Execute(&buf, data); err != nil {
		log.WithError(err).Fatal("error executing template")
	}

	// escreve arquivo sempre relativo ao diretório raiz do módulo
	outputPath := filepath.Join(".", fileName)
	if err := os.WriteFile(outputPath, buf.Bytes(), 0644); err != nil {
		log.WithError(err).Fatal("error writing file")
	}

	// roda gofmt no arquivo gerado
	if err := exec.Command("gofmt", "-w", outputPath).Run(); err != nil {
		log.WithError(err).Warn("could not format generated file with gofmt")
	}

	log.Infof("generated file: %s", outputPath)
}
